520	func generateCheckpointAISummary(ctx context.Context, scopedTranscript []byte, filesTouched []string, agentType types.AgentType) (*checkpoint.Summary, error) {
521		timeoutCtx, cancel := context.WithTimeout(ctx, checkpointSummaryTimeout)
522		timeoutDuration := checkpointSummaryTimeout
523		if deadline, ok := timeoutCtx.Deadline(); ok {
524			timeoutDuration = time.Until(deadline)
525		}
526		defer cancel()
