141	// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
142	func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
143		geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
144		if err != nil {
145			return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
146		}
147	
148		var entries []Entry
149		for _, msg := range geminiTranscript.Messages {
150			switch msg.Type {
151			case geminicli.MessageTypeUser:
152				if msg.Content != "" {
153					entries = append(entries, Entry{
154						Type:    EntryTypeUser,
155						Content: msg.Content,
156					})
157				}
158			case geminicli.MessageTypeGemini:
159				// Add assistant content
160				if msg.Content != "" {
161					entries = append(entries, Entry{
162						Type:    EntryTypeAssistant,
163						Content: msg.Content,
164					})
165				}
166				// Add tool calls
167				for _, tc := range msg.ToolCalls {
168					entries = append(entries, Entry{
169						Type:       EntryTypeTool,
170						ToolName:   tc.Name,
171						ToolDetail: extractGenericToolDetail(tc.Args),
172					})
173				}
174			}
175		}
176	
177		return entries, nil
178	}
