336	func splitCompactJSONL(data []byte) [][]byte {
337		var lines [][]byte
338		for _, line := range bytes.Split(data, []byte("\n")) {
339			line = bytes.TrimSpace(line)
340			if len(line) > 0 {
341				lines = append(lines, line)
342			}
343		}
344		return lines
345	}
346	
347	// BuildCondensedTranscript extracts a condensed view of the transcript.
348	// It processes user prompts, assistant responses, and tool calls into
349	// a simplified format suitable for LLM summarization.
350	func BuildCondensedTranscript(lines []transcript.Line) []Entry {
351		var entries []Entry
352	
353		for _, line := range lines {
354			switch line.Type {
355			case transcript.TypeUser:
356				if entry := extractUserEntry(line); entry != nil {
357					entries = append(entries, *entry)
358				}
359			case transcript.TypeAssistant:
360				assistantEntries := extractAssistantEntries(line)
361				entries = append(entries, assistantEntries...)
362			}
363		}
364	
365		return entries
366	}
367	
368	// skillContentPrefix identifies user messages that are skill content injections.
369	// These are injected after a Skill tool call and contain the full skill instructions.
370	const skillContentPrefix = "Base directory for this skill:"
371	
372	// extractUserEntry extracts a user entry from a transcript line.
373	// Returns nil if the line doesn't contain a valid user prompt or is skill content.
374	func extractUserEntry(line transcript.Line) *Entry {
375		content := transcript.ExtractUserContent(line.Message)
376		if content == "" {
377			return nil
378		}
379	
380		// Skip skill content injections - these are verbose skill instructions
381		// injected as user messages after Skill tool invocations in Claude Code.
382		// The prefix "Base directory for this skill:" is added by the superpowers
383		// plugin when loading skill content. This filtering reduces transcript noise
384		// since skill content is documentation, not user intent.
385		if strings.HasPrefix(content, skillContentPrefix) {
386			return nil
387		}
388	
389		return &Entry{
390			Type:    EntryTypeUser,
391			Content: content,
392		}
393	}
394	
395	// extractAssistantEntries extracts assistant and tool entries from a transcript line.
396	func extractAssistantEntries(line transcript.Line) []Entry {
397		var msg transcript.AssistantMessage
398		if err := json.Unmarshal(line.Message, &msg); err != nil {
399			return nil
400		}
401	
402		var entries []Entry
403	
404		for _, block := range msg.Content {
405			switch block.Type {
406			case transcript.ContentTypeText:
407				if block.Text != "" {
408					entries = append(entries, Entry{
409						Type:    EntryTypeAssistant,
410						Content: block.Text,
411					})
412				}
413			case transcript.ContentTypeToolUse:
414				var input transcript.ToolInput
415				_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
416	
417				detail := extractToolDetail(block.Name, input)
418	
419				entries = append(entries, Entry{
420					Type:       EntryTypeTool,
421					ToolName:   block.Name,
422					ToolDetail: detail,
423				})
424			}
425		}
426	
427		return entries
428	}
429	
430	// extractToolDetail extracts an appropriate detail string for a tool call.
431	// For tools in minimalDetailTools, only essential identifiers are shown.
432	// For other tools, the full detail chain is used.
433	func extractToolDetail(toolName string, input transcript.ToolInput) string {
434		// For minimal detail tools, extract only the essential identifier
435		if minimalDetailTools[toolName] {
436			switch toolName {
437			case "Skill":
438				return input.Skill
439			case "Read":
440				if input.FilePath != "" {
441					return input.FilePath
442				}
443				return input.NotebookPath
444			case "WebFetch":
445				return input.URL
446			}
447		}
448	
449		// For other tools, use the full detail chain
450		if input.Description != "" {
451			return input.Description
452		}
453		if input.Command != "" {
454			return input.Command
455		}
456		if input.FilePath != "" {
457			return input.FilePath
458		}
459		if input.NotebookPath != "" {
460			return input.NotebookPath
461		}
462		return input.Pattern
463	}
464	
465	// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
466	// The format is:
467	//
468	//	[User] user prompt here
469	//
470	//	[Assistant] assistant response here
471	//
472	//	[Tool] ToolName: description or file path
473	func FormatCondensedTranscript(input Input) string {
474		var sb strings.Builder
475	
476		for i, entry := range input.Transcript {
477			if i > 0 {
478				sb.WriteString("\n")
479			}
480	
481			switch entry.Type {
482			case EntryTypeUser:
483				sb.WriteString("[User] ")
484				sb.WriteString(entry.Content)
485				sb.WriteString("\n")
486			case EntryTypeAssistant:
487				sb.WriteString("[Assistant] ")
488				sb.WriteString(entry.Content)
489				sb.WriteString("\n")
490			case EntryTypeTool:
491				sb.WriteString("[Tool] ")
492				sb.WriteString(entry.ToolName)
493				if entry.ToolDetail != "" {
494					sb.WriteString(": ")
495					sb.WriteString(entry.ToolDetail)
496				}
497				sb.WriteString("\n")
498			}
499		}
500	
501		if len(input.FilesTouched) > 0 {
502			sb.WriteString("\n[Files Modified]\n")
503			for _, file := range input.FilesTouched {
504				fmt.Fprintf(&sb, "- %s\n", file)
505			}
506		}
507	
508		return sb.String()
509	}
