	if !env.IsError {
		t.Error("IsError = false; want true")
	}
	if env.APIErrorStatus == nil || *env.APIErrorStatus != 500 {
		t.Errorf("APIErrorStatus = %v; want *500", env.APIErrorStatus)
	}
}

